package com.thirdstone.commerce.platform.data;

import java.security.SecureRandom;

/**
 * Ids for orders, payments and shipments: 26 characters, the first 10 a
 * millisecond timestamp and the rest random (the ULID layout).
 *
 * <p>Generated by the service, so an id exists before the row is inserted and can
 * go into the event written in the same transaction. Sortable by creation time,
 * which keeps inserts at the end of the primary-key index; unguessable enough that
 * an id is not an enumeration handle (access is still checked by owner).
 */
public final class Ids {

    private static final char[] ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ".toCharArray();
    private static final SecureRandom RANDOM = new SecureRandom();

    public static String next() {
        char[] out = new char[26];
        long time = System.currentTimeMillis();
        for (int i = 9; i >= 0; i--) {
            out[i] = ALPHABET[(int) (time & 31)];
            time >>>= 5;
        }
        byte[] random = new byte[16];
        RANDOM.nextBytes(random);
        for (int i = 0; i < 16; i++) {
            out[10 + i] = ALPHABET[random[i] & 31];
        }
        return new String(out);
    }

    private Ids() {
    }
}
